interface User {
  id: number;
  name: string;
  email: string;
  role: "admin" | "member";
}

type UserPreview = Pick<User, "id" | "name">;
type NewUser = Omit<User, "id">;

function updateUser(id: number, changes: Partial<Omit<User, "id">>): string {
  return `user ${id}: ${Object.keys(changes).join(", ")}`;
}

const preview: UserPreview = { id: 1, name: "Ada" };
const draft: NewUser = { name: "Grace", email: "grace@example.com", role: "member" };

console.log(preview, draft.role);
console.log(updateUser(1, { name: "Ada Lovelace" }));

updateUser(1, { id: 2 });

interface User {
  id: number;
  name: string;
  role: "admin" | "member";
}

type Role = User["role"];

const permissions: Record<Role, string[]> = {
  admin: ["read", "write", "delete"],
  member: ["read"],
};

const frozen: Readonly<User> = { id: 1, name: "Ada", role: "admin" };

console.log(permissions[frozen.role]);

frozen.name = "Grace";

type Role = "admin" | "member";

function createUser(name: string, role: Role = "member") {
  return { id: Math.floor(Math.random() * 1000), name, role };
}

type Created = ReturnType<typeof createUser>;
type Args = Parameters<typeof createUser>;

async function loadIds() {
  return [1, 2, 3];
}

type Ids = Awaited<ReturnType<typeof loadIds>>;
type MaybeName = string | null | undefined;
type Name = NonNullable<MaybeName>;

const args: Args = ["Ada", "admin"];
const created: Created = createUser(...args);
const ids: Ids = await loadIds();
const name: Name = created.name;

console.log(created.role, ids.length, name);

type MyPartial<T> = { [K in keyof T]?: T[K] };

type Status = "idle" | "loading" | "done" | "error";
type Busy = Extract<Status, "loading">;
type Settled = Exclude<Status, "idle" | "loading">;

interface Config {
  server: { port: number; host: string };
}

